import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { deleteFromR2, downloadFromR2, isR2Configured, uploadToR2 } from "./r2-storage";

export type StoredDocument = { id: string; fileKey: string; mimeType: string };

// Document ids are generated by the app as 24 hex characters; refuse anything else so an id can never leave the folder.
const localPath = (id: string) => {
  if (!/^[a-f0-9]{24}$/.test(id)) throw new Error("Bad document id");
  return path.resolve(process.env.UPLOAD_DIR ?? "./uploads", "documents", id);
};

/** R2 key for a document. Includes the id, so it is unique and a new version never overwrites an old one. */
export const documentFileKey = (doc: { projectId: string; id: string; ext: string }) => `projects/${doc.projectId}/documents/${doc.id}.${doc.ext}`;

export async function saveDocumentFile(doc: StoredDocument, bytes: Uint8Array): Promise<void> {
  if (isR2Configured()) {
    await uploadToR2(bytes, doc.fileKey, doc.mimeType);
    return;
  }
  const file = localPath(doc.id);
  await mkdir(path.dirname(file), { recursive: true });
  await writeFile(file, bytes);
}

export async function readDocumentFile(doc: StoredDocument): Promise<Uint8Array> {
  if (isR2Configured()) {
    const bytes = await downloadFromR2(doc.fileKey);
    if (bytes) return bytes;
  }
  return readFile(localPath(doc.id));
}

export async function deleteDocumentFile(doc: StoredDocument): Promise<void> {
  if (isR2Configured()) await deleteFromR2(doc.fileKey);
  await rm(localPath(doc.id), { force: true });
}
